cypress_script:
describe('Tool Tips Page', () => {
  it('should display tooltip on hover over the input field', () => {
    cy.visit('https://demoqa.com/tool-tips');
    cy.get('#toolTipTextField').trigger('mouseover');
    cy.get('.tooltip-inner').should('be.visible');
  });

  it('should not show tooltip when not hovering', () => {
    cy.visit('https://demoqa.com/tool-tips');
    cy.get('#toolTipTextField').should('be.visible');
    cy.get('.tooltip-inner').should('not.exist');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Tool Tips Page', () => {
  test('should display tooltip on hover over the input field', async ({ page }) => {
    await page.goto('https://demoqa.com/tool-tips');
    const inputField = page.locator('#toolTipTextField');
    await inputField.hover();
    const tooltip = page.locator('.tooltip-inner');
    await expect(tooltip).toBeVisible();
  });

  test('should not show tooltip when not hovering', async ({ page }) => {
    await page.goto('https://demoqa.com/tool-tips');
    const inputField = page.locator('#toolTipTextField');
    await expect(inputField).toBeVisible();
    const tooltip = page.locator('.tooltip-inner');
    await expect(tooltip).not.toBeVisible();
  });
});
